/**
 * Vendor Document Type Constants
 * Types of vendor documents
 */

export const VENDOR_DOCUMENT_TYPE = {
  // Document Types
  TYPES: {
    NID: 'nid',
    PASSPORT: 'passport',
    TRADE_LICENSE: 'trade_license',
    TIN: 'tin',
    VAT: 'vat',
    BANK_STATEMENT: 'bank_statement',
    TAX_CERTIFICATE: 'tax_certificate',
    AUDIT_REPORT: 'audit_report',
    PHOTO: 'photo',
    SIGNATURE: 'signature',
    OTHER: 'other',
  } as const,

  // Document Categories
  CATEGORIES: {
    IDENTITY: 'identity',
    BUSINESS: 'business',
    FINANCIAL: 'financial',
    LEGAL: 'legal',
    OTHER: 'other',
  } as const,

  // Document Importance
  IMPORTANCE: {
    REQUIRED: 'required',
    OPTIONAL: 'optional',
    RECOMMENDED: 'recommended',
  } as const,

  // Document Verification
  VERIFICATION: {
    REQUIRED: 'required',
    OPTIONAL: 'optional',
    MANUAL: 'manual',
    AUTOMATED: 'automated',
  } as const,

  // Document Processing Times (in hours)
  PROCESSING_TIMES: {
    NID: 24,
    PASSPORT: 48,
    TRADE_LICENSE: 72,
    TIN: 24,
    VAT: 24,
    BANK_STATEMENT: 12,
    TAX_CERTIFICATE: 24,
    AUDIT_REPORT: 48,
    PHOTO: 2,
    SIGNATURE: 2,
    OTHER: 24,
  } as const,
} as const;

// Document Types
export type VendorDocumentTypeType =
  (typeof VENDOR_DOCUMENT_TYPE.TYPES)[keyof typeof VENDOR_DOCUMENT_TYPE.TYPES];

// Document Categories
export type VendorDocumentTypeCategory =
  (typeof VENDOR_DOCUMENT_TYPE.CATEGORIES)[keyof typeof VENDOR_DOCUMENT_TYPE.CATEGORIES];

// Document Importance
export type VendorDocumentImportance =
  (typeof VENDOR_DOCUMENT_TYPE.IMPORTANCE)[keyof typeof VENDOR_DOCUMENT_TYPE.IMPORTANCE];

// Document Verification
export type VendorDocumentVerification =
  (typeof VENDOR_DOCUMENT_TYPE.VERIFICATION)[keyof typeof VENDOR_DOCUMENT_TYPE.VERIFICATION];

// Utility Functions
export function vendorDocumentTypeGetLabel(type: VendorDocumentTypeType): string {
  const labels: Record<VendorDocumentTypeType, string> = {
    [VENDOR_DOCUMENT_TYPE.TYPES.NID]: 'National ID',
    [VENDOR_DOCUMENT_TYPE.TYPES.PASSPORT]: 'Passport',
    [VENDOR_DOCUMENT_TYPE.TYPES.TRADE_LICENSE]: 'Trade License',
    [VENDOR_DOCUMENT_TYPE.TYPES.TIN]: 'TIN Certificate',
    [VENDOR_DOCUMENT_TYPE.TYPES.VAT]: 'VAT Registration',
    [VENDOR_DOCUMENT_TYPE.TYPES.BANK_STATEMENT]: 'Bank Statement',
    [VENDOR_DOCUMENT_TYPE.TYPES.TAX_CERTIFICATE]: 'Tax Certificate',
    [VENDOR_DOCUMENT_TYPE.TYPES.AUDIT_REPORT]: 'Audit Report',
    [VENDOR_DOCUMENT_TYPE.TYPES.PHOTO]: 'Photo',
    [VENDOR_DOCUMENT_TYPE.TYPES.SIGNATURE]: 'Signature',
    [VENDOR_DOCUMENT_TYPE.TYPES.OTHER]: 'Other',
  };
  return labels[type] || 'Unknown';
}

export function vendorDocumentTypeGetCategory(
  type: VendorDocumentTypeType
): VendorDocumentTypeCategory {
  const categories: Record<VendorDocumentTypeType, VendorDocumentTypeCategory> = {
    [VENDOR_DOCUMENT_TYPE.TYPES.NID]: VENDOR_DOCUMENT_TYPE.CATEGORIES.IDENTITY,
    [VENDOR_DOCUMENT_TYPE.TYPES.PASSPORT]: VENDOR_DOCUMENT_TYPE.CATEGORIES.IDENTITY,
    [VENDOR_DOCUMENT_TYPE.TYPES.TRADE_LICENSE]: VENDOR_DOCUMENT_TYPE.CATEGORIES.BUSINESS,
    [VENDOR_DOCUMENT_TYPE.TYPES.TIN]: VENDOR_DOCUMENT_TYPE.CATEGORIES.BUSINESS,
    [VENDOR_DOCUMENT_TYPE.TYPES.VAT]: VENDOR_DOCUMENT_TYPE.CATEGORIES.BUSINESS,
    [VENDOR_DOCUMENT_TYPE.TYPES.BANK_STATEMENT]: VENDOR_DOCUMENT_TYPE.CATEGORIES.FINANCIAL,
    [VENDOR_DOCUMENT_TYPE.TYPES.TAX_CERTIFICATE]: VENDOR_DOCUMENT_TYPE.CATEGORIES.FINANCIAL,
    [VENDOR_DOCUMENT_TYPE.TYPES.AUDIT_REPORT]: VENDOR_DOCUMENT_TYPE.CATEGORIES.FINANCIAL,
    [VENDOR_DOCUMENT_TYPE.TYPES.PHOTO]: VENDOR_DOCUMENT_TYPE.CATEGORIES.IDENTITY,
    [VENDOR_DOCUMENT_TYPE.TYPES.SIGNATURE]: VENDOR_DOCUMENT_TYPE.CATEGORIES.LEGAL,
    [VENDOR_DOCUMENT_TYPE.TYPES.OTHER]: VENDOR_DOCUMENT_TYPE.CATEGORIES.OTHER,
  };
  return categories[type] || VENDOR_DOCUMENT_TYPE.CATEGORIES.OTHER;
}

export function vendorDocumentTypeGetImportance(
  type: VendorDocumentTypeType
): VendorDocumentImportance {
  const importance: Record<VendorDocumentTypeType, VendorDocumentImportance> = {
    [VENDOR_DOCUMENT_TYPE.TYPES.NID]: VENDOR_DOCUMENT_TYPE.IMPORTANCE.REQUIRED,
    [VENDOR_DOCUMENT_TYPE.TYPES.PASSPORT]: VENDOR_DOCUMENT_TYPE.IMPORTANCE.OPTIONAL,
    [VENDOR_DOCUMENT_TYPE.TYPES.TRADE_LICENSE]: VENDOR_DOCUMENT_TYPE.IMPORTANCE.REQUIRED,
    [VENDOR_DOCUMENT_TYPE.TYPES.TIN]: VENDOR_DOCUMENT_TYPE.IMPORTANCE.REQUIRED,
    [VENDOR_DOCUMENT_TYPE.TYPES.VAT]: VENDOR_DOCUMENT_TYPE.IMPORTANCE.REQUIRED,
    [VENDOR_DOCUMENT_TYPE.TYPES.BANK_STATEMENT]: VENDOR_DOCUMENT_TYPE.IMPORTANCE.REQUIRED,
    [VENDOR_DOCUMENT_TYPE.TYPES.TAX_CERTIFICATE]: VENDOR_DOCUMENT_TYPE.IMPORTANCE.OPTIONAL,
    [VENDOR_DOCUMENT_TYPE.TYPES.AUDIT_REPORT]: VENDOR_DOCUMENT_TYPE.IMPORTANCE.OPTIONAL,
    [VENDOR_DOCUMENT_TYPE.TYPES.PHOTO]: VENDOR_DOCUMENT_TYPE.IMPORTANCE.REQUIRED,
    [VENDOR_DOCUMENT_TYPE.TYPES.SIGNATURE]: VENDOR_DOCUMENT_TYPE.IMPORTANCE.REQUIRED,
    [VENDOR_DOCUMENT_TYPE.TYPES.OTHER]: VENDOR_DOCUMENT_TYPE.IMPORTANCE.OPTIONAL,
  };
  return importance[type] || VENDOR_DOCUMENT_TYPE.IMPORTANCE.OPTIONAL;
}

export function vendorDocumentTypeGetVerification(
  type: VendorDocumentTypeType
): VendorDocumentVerification {
  const verification: Record<VendorDocumentTypeType, VendorDocumentVerification> = {
    [VENDOR_DOCUMENT_TYPE.TYPES.NID]: VENDOR_DOCUMENT_TYPE.VERIFICATION.AUTOMATED,
    [VENDOR_DOCUMENT_TYPE.TYPES.PASSPORT]: VENDOR_DOCUMENT_TYPE.VERIFICATION.MANUAL,
    [VENDOR_DOCUMENT_TYPE.TYPES.TRADE_LICENSE]: VENDOR_DOCUMENT_TYPE.VERIFICATION.MANUAL,
    [VENDOR_DOCUMENT_TYPE.TYPES.TIN]: VENDOR_DOCUMENT_TYPE.VERIFICATION.AUTOMATED,
    [VENDOR_DOCUMENT_TYPE.TYPES.VAT]: VENDOR_DOCUMENT_TYPE.VERIFICATION.AUTOMATED,
    [VENDOR_DOCUMENT_TYPE.TYPES.BANK_STATEMENT]: VENDOR_DOCUMENT_TYPE.VERIFICATION.MANUAL,
    [VENDOR_DOCUMENT_TYPE.TYPES.TAX_CERTIFICATE]: VENDOR_DOCUMENT_TYPE.VERIFICATION.MANUAL,
    [VENDOR_DOCUMENT_TYPE.TYPES.AUDIT_REPORT]: VENDOR_DOCUMENT_TYPE.VERIFICATION.MANUAL,
    [VENDOR_DOCUMENT_TYPE.TYPES.PHOTO]: VENDOR_DOCUMENT_TYPE.VERIFICATION.AUTOMATED,
    [VENDOR_DOCUMENT_TYPE.TYPES.SIGNATURE]: VENDOR_DOCUMENT_TYPE.VERIFICATION.MANUAL,
    [VENDOR_DOCUMENT_TYPE.TYPES.OTHER]: VENDOR_DOCUMENT_TYPE.VERIFICATION.MANUAL,
  };
  return verification[type] || VENDOR_DOCUMENT_TYPE.VERIFICATION.MANUAL;
}

export function vendorDocumentTypeGetProcessingTime(type: VendorDocumentTypeType): number {
  const times: Record<VendorDocumentTypeType, number> = {
    [VENDOR_DOCUMENT_TYPE.TYPES.NID]: VENDOR_DOCUMENT_TYPE.PROCESSING_TIMES.NID,
    [VENDOR_DOCUMENT_TYPE.TYPES.PASSPORT]: VENDOR_DOCUMENT_TYPE.PROCESSING_TIMES.PASSPORT,
    [VENDOR_DOCUMENT_TYPE.TYPES.TRADE_LICENSE]: VENDOR_DOCUMENT_TYPE.PROCESSING_TIMES.TRADE_LICENSE,
    [VENDOR_DOCUMENT_TYPE.TYPES.TIN]: VENDOR_DOCUMENT_TYPE.PROCESSING_TIMES.TIN,
    [VENDOR_DOCUMENT_TYPE.TYPES.VAT]: VENDOR_DOCUMENT_TYPE.PROCESSING_TIMES.VAT,
    [VENDOR_DOCUMENT_TYPE.TYPES.BANK_STATEMENT]:
      VENDOR_DOCUMENT_TYPE.PROCESSING_TIMES.BANK_STATEMENT,
    [VENDOR_DOCUMENT_TYPE.TYPES.TAX_CERTIFICATE]:
      VENDOR_DOCUMENT_TYPE.PROCESSING_TIMES.TAX_CERTIFICATE,
    [VENDOR_DOCUMENT_TYPE.TYPES.AUDIT_REPORT]: VENDOR_DOCUMENT_TYPE.PROCESSING_TIMES.AUDIT_REPORT,
    [VENDOR_DOCUMENT_TYPE.TYPES.PHOTO]: VENDOR_DOCUMENT_TYPE.PROCESSING_TIMES.PHOTO,
    [VENDOR_DOCUMENT_TYPE.TYPES.SIGNATURE]: VENDOR_DOCUMENT_TYPE.PROCESSING_TIMES.SIGNATURE,
    [VENDOR_DOCUMENT_TYPE.TYPES.OTHER]: VENDOR_DOCUMENT_TYPE.PROCESSING_TIMES.OTHER,
  };
  return times[type] || 24;
}
